// Parsear el input de Telegram.
//
// C-27: este nodo es un PARSER PURO -- no lee ni escribe estado. La version
// anterior mantenia un gate de captura en $getWorkflowStaticData('global'),
// que en n8n 2.4.4 NO sobrevive entre ejecuciones (verificado sobre
// ejecuciones reales: el gate se escribia y 32 segundos despues no estaba).
// El estado de la conversacion vive ahora en Postgres
// (reserva_temporal.datos_captura) y lo consulta el sub-flujo, que es quien
// puede decidir con la base a la vista.
//
// Consecuencia de diseno: todo texto que no sea un comando reconocido se
// despacha a sub-flujo-crear-turno con `payload.respuesta_captura`, ADEMAS
// del parseo por forma que ya se hacia. El sub-flujo desempata: si hay una
// captura pendiente, el texto es una respuesta; si no, vale la forma. Asi un
// "15" mientras el bot espera un DNI es un DNI invalido y no el slot 15, sin
// que el orquestador necesite saber nada.
const input = ($input.all()[0] && $input.all()[0].json) || {};

let text = '';
let chatId = null;
let callbackQueryId = null;

if (input.message) {
  text = input.message.text || '';
  chatId = input.message.chat && input.message.chat.id;
} else if (input.callback_query) {
  text = input.callback_query.data || '';
  chatId = input.callback_query.message && input.callback_query.message.chat && input.callback_query.message.chat.id;
  callbackQueryId = input.callback_query.id;
}

const textRaw = String(text || '');
const textLower = textRaw.toLowerCase().trim();
let comando = 'desconocido';
const payload = {};

// ======================================================================
// HELPERS (timezone Argentina)
// ======================================================================
function fmtArgentina(d) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Argentina/Buenos_Aires',
    year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(d);
  const y = parts.find(p => p.type === 'year').value;
  const m = parts.find(p => p.type === 'month').value;
  const dd = parts.find(p => p.type === 'day').value;
  return `${y}-${m}-${dd}`;
}

function addDays(yyyy_mm_dd, n) {
  const [y, m, d] = yyyy_mm_dd.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  date.setUTCDate(date.getUTCDate() + n);
  const yy = date.getUTCFullYear();
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

const hoyArgentina = () => fmtArgentina(new Date());

// ======================================================================
// PRECEDENCIA: comando reconocido > texto libre.
//
// Un comando reconocido SIEMPRE gana y marca `fresh_start`, que el
// sub-flujo usa para abandonar una captura pendiente. Ese es el escape
// hatch: sin el, quien deja una reserva a mitad de pregunta queda atrapado
// hasta que expire la reserva, porque cualquier mensaje suyo se leeria como
// respuesta a una pregunta que ya olvido.
// ======================================================================
const esCallbackReconocido = textRaw === 'cmd:crear' || textRaw.startsWith('cmd:crear:') ||
  textRaw === 'cmd:cancelar' || textRaw.startsWith('cmd:cancelar:') ||
  textRaw === 'cmd:reprogramar' || textRaw.startsWith('cmd:reprogramar:') ||
  textRaw === 'cmd:confirmar' || textRaw.startsWith('cmd:confirmar:') ||
  textRaw === 'cmd:menu';

const esComandoTexto = textLower.startsWith('/reservar') || textLower === 'reservar' || textLower.includes('quiero un turno') || textLower.includes('sacar turno') || textLower.startsWith('reservar:') || textLower.startsWith('reservar_lista_') ||
  textLower.startsWith('/cancelar') || textLower === 'cancelar' || textLower.includes('dar de baja') || textLower.startsWith('cancelar:') ||
  textLower.startsWith('/reprogramar') || textLower === 'reprogramar' || textLower.includes('cambiar turno') || textLower.includes('mover turno') || textLower.startsWith('reprogramar:');

const comandoReconocido = esCallbackReconocido || esComandoTexto;

if (comandoReconocido) {
  payload.fresh_start = true;

  // 'cmd:menu' entra aca A PROPOSITO y no matchea ninguna rama de abajo:
  // necesita marcar fresh_start (para abandonar una captura pendiente) pero
  // NO tiene sub-flujo propio. Al no asignar `comando`, queda en su valor
  // inicial 'desconocido' y el Switch lo manda al fallback, que es
  // "Telegram - Mensaje de Ayuda" -- o sea, el menu principal. No agregar una
  // rama para 'cmd:menu': la ausencia ES el ruteo.

  // ======================================================================
  // 1) Callbacks de botones inline
  // ======================================================================
  if (textRaw === 'cmd:crear' || textRaw.startsWith('cmd:crear:')) {
    comando = 'crear';
    if (textRaw.startsWith('cmd:crear:rango:')) {
      const rangoPart = textRaw.substring('cmd:crear:rango:'.length);
      payload.rango = rangoPart;
      if (rangoPart !== 'exacto') {
        let daysToAdd = 0;
        if (rangoPart === 'inmediato') daysToAdd = 1;
        else if (rangoPart === '2semanas') daysToAdd = 14;
        else if (rangoPart === '1mes') daysToAdd = 28;
        if (daysToAdd > 0) {
          payload.fecha = addDays(hoyArgentina(), daysToAdd);
        }
      }
    } else if (textRaw.startsWith('cmd:crear:slot:')) {
      // La fecha viaja en el callback: cmd:crear:slot:HH:MM:f:YYYY-MM-DD.
      // Es stateless a proposito -- ver el comentario de cabecera.
      const _rest = textRaw.substring('cmd:crear:slot:'.length);
      const _fIdx = _rest.indexOf(':f:');
      if (_fIdx >= 0) {
        payload.slot = _rest.substring(0, _fIdx);
        payload.fecha = _rest.substring(_fIdx + 3);
      } else {
        payload.slot = _rest;
      }
      // Una seleccion de slot arranca una reserva nueva: no es fresh_start
      // (no hay que abandonar nada, todavia no hay captura), pero tampoco
      // debe arrastrar una respuesta de captura.
      payload.fresh_start = false;
    } else if (textRaw.startsWith('cmd:crear:fecha:')) {
      payload.fecha = textRaw.substring('cmd:crear:fecha:'.length);
    }
  } else if (textRaw === 'cmd:cancelar' || textRaw.startsWith('cmd:cancelar:')) {
    comando = 'cancelar';
    if (textRaw.startsWith('cmd:cancelar:turno_id:')) {
      payload.turno_id = textRaw.substring('cmd:cancelar:turno_id:'.length);
    }
  } else if (textRaw === 'cmd:reprogramar' || textRaw.startsWith('cmd:reprogramar:')) {
    comando = 'reprogramar';
    if (textRaw.startsWith('cmd:reprogramar:turno_id:')) {
      payload.turno_id = textRaw.substring('cmd:reprogramar:turno_id:'.length);
    }
  }
  // Confirmacion de asistencia desde el recordatorio. No cambia el estado
  // del turno ni nada que vea el profesional: el turno ya estaba CONFIRMADO
  // y sigue estandolo. Solo se le agradece al paciente. La marca que va a
  // necesitar el escalado (segundo recordatorio + cancelacion automatica)
  // todavia no existe -- se agrega cuando se construya ese change.
  else if (textRaw === 'cmd:confirmar' || textRaw.startsWith('cmd:confirmar:')) {
    comando = 'confirmar';
    if (textRaw.startsWith('cmd:confirmar:turno_id:')) {
      payload.turno_id = textRaw.substring('cmd:confirmar:turno_id:'.length);
    }
  }
  // ======================================================================
  // 5) Comandos de texto (slash + lenguaje natural)
  // ======================================================================
  else if (textLower.startsWith('/reservar') || textLower === 'reservar' || textLower.includes('quiero un turno') || textLower.includes('sacar turno') || textLower.startsWith('reservar:') || textLower.startsWith('reservar_lista_')) {
    comando = 'crear';
  } else if (textLower.startsWith('/cancelar') || textLower === 'cancelar' || textLower.includes('dar de baja') || textLower.startsWith('cancelar:')) {
    comando = 'cancelar';
    if (textLower.startsWith('cancelar:')) {
      payload.turno_id = text.split(':')[1];
    }
  } else if (textLower.startsWith('/reprogramar') || textLower === 'reprogramar' || textLower.includes('cambiar turno') || textLower.includes('mover turno') || textLower.startsWith('reprogramar:')) {
    comando = 'reprogramar';
    if (textLower.startsWith('reprogramar:')) {
      payload.turno_id = text.split(':')[1];
    }
  }
} else {
  // ======================================================================
  // Texto libre. Se parsea por forma igual que siempre Y se adjunta como
  // posible respuesta de captura. Los dos viajan juntos; el sub-flujo
  // desempata contra la base.
  // ======================================================================
  comando = 'crear';
  payload.respuesta_captura = textRaw;

  // 2) Input de hora HH:MM
  if (/^\d{1,2}:\d{2}$/.test(textRaw.trim())) {
    payload.slot = textRaw.trim();
  }
  // 3) Input de numero (slot_numero)
  else if (/^\d+$/.test(textRaw.trim())) {
    const num = parseInt(textRaw.trim(), 10);
    if (num >= 1 && num <= 20) {
      payload.slot_numero = num;
    }
  }
  // 4) Input de fecha DD/MM/AAAA
  else if (/^(\d{2})\/(\d{2})\/(\d{4})$/.test(textRaw.trim())) {
    payload.fecha_raw = textRaw.trim();
    const _p = textRaw.trim().split('/');
    const _dd = parseInt(_p[0], 10);
    const _mm = parseInt(_p[1], 10) - 1;
    const _yy = parseInt(_p[2], 10);
    const _parsed = new Date(_yy, _mm, _dd);
    if (_parsed.getDate() === _dd && _parsed.getMonth() === _mm && _parsed.getFullYear() === _yy) {
      const _iso = String(_yy) + '-' + String(_mm + 1).padStart(2, '0') + '-' + String(_dd).padStart(2, '0');
      const _todayStr = hoyArgentina();
      const _maxStr = addDays(_todayStr, 90);
      if (_iso >= _todayStr && _iso <= _maxStr) {
        payload.fecha = _iso;
      }
    }
  }
}

return [{
  json: {
    comando: comando,
    chat_id: chatId,
    callback_query_id: callbackQueryId,
    text: textRaw,
    payload: payload
  }
}];

// Lee el retorno de sub-flujo-crear-turno y decide si mostrar la ayuda.
//
// C-27: la version anterior de este nodo (Code - Sync Captura) sincronizaba
// un gate de captura en $getWorkflowStaticData('global'). Ese gate ya no
// existe -- el estado vive en Postgres y lo consulta el sub-flujo. Lo unico
// que queda acá es el fail-safe.
//
// El chat_id se lee del nodo "Normalizar Comando", no del output del Execute
// Workflow, porque chat_id no sobrevive al salto entre workflows (mismo
// patron que Code - Verificar Slots en el sub-flujo).
let chatId = null;
try {
  chatId = $('Normalizar Comando').first().json.chat_id;
} catch (e) {}

const input = ($input.all()[0] && $input.all()[0].json) || {};
let mostrarAyuda = input.mostrar_ayuda;

// Execute Crear Turno tiene onError: "continueRegularOutput": si el
// sub-workflow falla no devuelve nada. Fail-safe: se muestra la ayuda en vez
// de dejar al usuario en silencio.
if (mostrarAyuda === undefined) {
  mostrarAyuda = true;
}

return [{
  json: {
    chat_id: chatId,
    mostrar_ayuda: !!mostrarAyuda
  }
}];

// Lee el resultado de PUT /turnos/{id}/confirmar-asistencia y arma la
// respuesta al paciente.
//
// chat_id por nodo nombrado: la respuesta HTTP reemplaza el item y no trae
// chat_id. Es la misma regla que rompio a sub-flujo-cancelar-turno, donde
// Code - Formatear Respuesta lo leia de $json y recibia undefined.
let chatId = null;
try {
  chatId = $('Normalizar Comando').first().json.chat_id;
} catch (e) {}

// neverError + fullResponse son obligatorios en el nodo HTTP: sin ellos un
// 404 o un 409 tiran excepcion y este nodo nunca corre, dejando al paciente
// sin ninguna respuesta.
const input = ($input.all()[0] && $input.all()[0].json) || {};
const statusCode = input.statusCode;
const body = input.body || {};
const ok = typeof statusCode === 'number' && statusCode >= 200 && statusCode < 300;

let mensaje;
if (ok) {
  mensaje = '✅ ¡Gracias por confirmar! Te esperamos.';
} else if (statusCode === 404) {
  mensaje = 'No encontramos ese turno. Puede que ya no exista.';
} else if (statusCode === 409) {
  // El backend responde 409 cuando el turno no esta CONFIRMADO: cancelado,
  // completado o todavia en reserva temporal.
  mensaje = 'Ese turno ya no esta vigente, asi que no pudimos registrar tu confirmacion.';
} else {
  mensaje = 'No pudimos registrar tu confirmacion. Intentalo de nuevo en un rato.';
}

return [{
  json: {
    chat_id: chatId,
    exito: ok,
    mensaje: mensaje,
    detalle: body.detail || null
  }
}];
